package com.example.desktop;

import javafx.geometry.Insets;
import javafx.scene.Node;
import javafx.scene.control.*;
import javafx.scene.layout.*;

public final class Section24Views {
  private Section24Views(){}
  public static Node create(){
    BorderPane root=new BorderPane();VBox head=new VBox(5);head.setPadding(new Insets(18,22,10,22));
    Label h=new Label("Section 24 — Patient Care Areas");h.setStyle("-fx-font-size:21px;-fx-font-weight:bold;-fx-text-fill:#14213d;");
    Label s=new Label("Quick reference for basic, intermediate and critical care areas, bonding, receptacles, isolated systems and associated low-voltage auxiliary circuits.");s.setWrapText(true);s.setStyle("-fx-text-fill:#64748b;");head.getChildren().addAll(h,s);
    TabPane tabs=new TabPane();tabs.getTabs().addAll(tab("Patient Care Environment",environment()),tab("Basic Care",basic()),tab("Intermediate / Critical",critical()),tab("Isolated Systems",isolated()),tab("Low Voltage / Class 1-2",Section16Views.createEmbedded("Use this for low-voltage signalling, control or auxiliary circuits associated with patient-care equipment when Section 16 applies. Section 24 requirements and the equipment listing still take priority where they modify the general Class 1/Class 2 rules.")));root.setTop(head);root.setCenter(tabs);return root;
  }
  private static Node environment(){TextField len=tf("2.1"),wid=tf("0.9");TextArea out=new TextArea();out.setEditable(false);out.setWrapText(true);Button calc=new Button("Calculate patient care environment footprint");calc.setOnAction(e->{try{double l=n(len),w=n(wid);out.setText("PATIENT CARE ENVIRONMENT\n\nBed/table footprint entered: "+f(l)+" m × "+f(w)+" m\nCEC zone extends 1.5 m beyond the perimeter in plan.\nCalculated planning footprint: "+f(l+3)+" m × "+f(w+3)+" m\nVertical extent: to 2.3 m above floor.\n\nUse this as a layout visualization only; the actual patient care environment is based on the normal location of the bed/table/supporting mechanism and treatment equipment.\n\nReference: CEC 2024 Section 24 definitions / Rule 24-100 context.");}catch(Exception ex){out.setText("Check inputs: "+ex.getMessage());}});VBox left=new VBox(12,card("Patient care environment boundary","The CEC patient care environment includes the treatment zone around the patient-supporting mechanism: 1.5 m beyond its perimeter and up to 2.3 m above the floor."),gridCard("Planning calculator",grid("Bed/table length (m)",len,"Bed/table width (m)",wid)),calc);left.setPadding(new Insets(16));SplitPane sp=new SplitPane(scroll(left),out);sp.setDividerPositions(.5);return sp;}
  private static Node basic(){return page(card("Classification","Section 24 distinguishes basic, intermediate and critical care areas. The designation matters because circuit, bonding and receptacle requirements become more stringent as care level increases."),card("Basic-care branch circuits","CEC 2024 Rule 24-104 uses grounded distribution for basic-care receptacle/permanently connected equipment circuits. Branch-circuit insulated conductors are copper and not smaller than No. 12 AWG; patient-care-environment circuits are generally 2-wire except for multi-phase equipment."),card("Voltage and circuit scope","Basic-care patient-care-environment branch circuits are generally limited to not more than 150 V-to-ground except for permitted special-purpose/permanently connected equipment. Circuits serving medical equipment in the patient care environment are kept dedicated to that environment, subject to the adjacent-environment allowance."),card("Bonding","Rule 24-106 adds patient-care bonding requirements beyond ordinary Section 10 practice. Think insulated copper bonding conductors, dedicated bonding paths, and special rules where multiple panels serve the environment."),card("Receptacles","Rule 24-108 includes special placement requirements. Examples include receptacles in routinely wet-cleaned areas being at least 300 mm above the floor and bathroom/washroom receptacles being located in relation to the wash basin."));}
  private static Node critical(){return page(card("Intermediate / critical circuits","Rule 24-112 permits grounded systems meeting the basic-care requirements or isolated systems meeting Rule 24-200. Single-phase patient-care-environment branch circuits remain 2-wire except for multi-phase equipment."),card("Bonding","Rule 24-114 carries the patient-care bonding requirements into intermediate and critical care areas whether the source is grounded or isolated."),card("Receptacles","Rule 24-116 builds on the basic-care receptacle rules. Receptacles supplied from an isolated system must be identified as isolated-system receptacles."),card("Standing fluids / drenching","Rule 24-118 requires receptacles in areas subject to standing fluids or drenching to be protected by Class A GFCI or supplied by a compliant isolated system."));}
  private static Node isolated(){return page(card("Sources","Rule 24-202 permits an isolating transformer, motor-generator set, or suitably isolated battery-powered inverter as the source for an isolated system."),card("Ungrounded secondary","The isolated-system conductors are not deliberately grounded except through the isolation-monitoring impedance. Keep isolated-system wiring separate from grounded circuits as required."),card("Conductor identification","CEC 2024 identifies the two isolated-system circuit conductors using orange and brown insulation. This is a useful exam clue when isolated patient-care power is being described."),card("Think system, not just transformer","For exam questions, remember the isolation transformer is only one part. The isolated system also involves conductor type, identification, monitoring, wiring separation, receptacle identification and bonding requirements."));}
  private static VBox page(Node... nodes){VBox v=new VBox(12,nodes);v.setPadding(new Insets(18));return v;}private static VBox card(String t,String x){Label h=new Label(t);h.setStyle("-fx-font-size:16px;-fx-font-weight:bold;");Label b=new Label(x);b.setWrapText(true);b.setStyle("-fx-text-fill:#475569;");VBox v=new VBox(7,h,b);v.setPadding(new Insets(14));v.setStyle("-fx-background-color:white;-fx-border-color:#e2e8f0;-fx-background-radius:10;-fx-border-radius:10;");return v;}private static VBox gridCard(String t,GridPane g){Label h=new Label(t);h.setStyle("-fx-font-size:16px;-fx-font-weight:bold;");VBox v=new VBox(8,h,g);v.setPadding(new Insets(14));v.setStyle("-fx-background-color:white;-fx-border-color:#e2e8f0;-fx-background-radius:10;-fx-border-radius:10;");return v;}private static GridPane grid(Object... p){GridPane g=new GridPane();g.setHgap(12);g.setVgap(8);for(int i=0;i<p.length;i+=2){g.add(new Label(String.valueOf(p[i])),0,i/2);g.add((Node)p[i+1],1,i/2);}return g;}private static ScrollPane scroll(Node n){ScrollPane s=new ScrollPane(n);s.setFitToWidth(true);return s;}private static Tab tab(String t,Node n){Tab x=new Tab(t,n);x.setClosable(false);return x;}private static TextField tf(String s){TextField t=new TextField(s);t.setMaxWidth(250);return t;}private static double n(TextField f){return Double.parseDouble(f.getText().trim());}private static String f(double d){return String.format("%.2f",d);}
}
